#include <iostream>
using namespace std;

int main() {
    long long n;
    int x;
    cin >> n >> x;

    // The sequence of swaps repeats every 3 moves:
    // Move 1 (odd): swap 0 and 1
    // Move 2 (even): swap 1 and 2
    // Move 3 (odd): swap 0 and 1
    // Move 4 (even): swap 1 and 2
    // ...
    // So the pattern of swaps is: swap(0,1), swap(1,2), swap(0,1), swap(1,2), ...
    // This forms a cycle of length 3 in terms of the permutation applied.

    // We can model the position transformations directly.
    // Let's track where each position maps after each move.
    // Instead of simulating n moves (which is too large), we find the cycle.

    // The permutation after 1 move: 0->1, 1->0, 2->2
    // After 2 moves: 0->1->2, 1->0->0, 2->2->1 => 0->2, 1->0, 2->1
    // After 3 moves: apply swap(0,1) to the result of 2 moves
    //   0->2->2, 1->0->1, 2->1->0 => 0->2, 1->1, 2->0
    // After 4 moves: apply swap(1,2) to the result of 3 moves
    //   0->2->1, 1->1->2, 2->0->0 => 0->1, 1->2, 2->0
    // After 5 moves: apply swap(0,1) to the result of 4 moves
    //   0->1->0, 1->2->2, 2->0->1 => 0->0, 1->2, 2->1
    // After 6 moves: apply swap(1,2) to the result of 5 moves
    //   0->0->0, 1->2->1, 2->1->2 => 0->0, 1->1, 2->2 (identity!)

    // So the cycle length is 6.
    // We need to find the inverse: given final position x after n moves, find initial position.
    // Equivalently, find the permutation P such that P(initial) = final, then initial = P^{-1}(final).

    // Let's compute the permutation for n mod 6 moves.
    int r = n % 6;

    // We'll compute the inverse permutation.
    // Let's define the forward permutation for each remainder.
    // perm[i] = where position i goes after r moves.
    int perm[3];

    if (r == 0) {
        perm[0] = 0; perm[1] = 1; perm[2] = 2;
    } else if (r == 1) {
        perm[0] = 1; perm[1] = 0; perm[2] = 2;
    } else if (r == 2) {
        perm[0] = 2; perm[1] = 0; perm[2] = 1;
    } else if (r == 3) {
        perm[0] = 2; perm[1] = 1; perm[2] = 0;
    } else if (r == 4) {
        perm[0] = 1; perm[1] = 2; perm[2] = 0;
    } else { // r == 5
        perm[0] = 0; perm[1] = 2; perm[2] = 1;
    }

    // Now find inverse: inv_perm[perm[i]] = i
    int inv_perm[3];
    for (int i = 0; i < 3; i++) {
        inv_perm[perm[i]] = i;
    }

    cout << inv_perm[x] << endl;

    return 0;
}
